import { describe, expect, test } from 'bun:test';
import {
	b64urlToBytes,
	bytesToB64url,
	vapidAuthHeader,
	encryptPayload,
	vapidFromEnv,
	type VapidKeys,
} from '../apps/app/src/server/web-push.ts';

/**
 * Web Push crypto (RFC 8291/8292) over pure WebCrypto. The VAPID JWT is
 * verifiable against its own public key, and the encrypted body carries a
 * well-formed aes128gcm header. LOCAL VERIFIED.
 */

// A real VAPID keypair (generated by web-push generate-vapid-keys; test-only).
const KEYS: VapidKeys = {
	publicKey: 'BFm7zEzMLM9wUTecqJRZEurjWpDyfK4ulARPyl6VwX_x9aTQN0fdpu6wOIUJBw4en_RlJdhuMOWgRixdzRtTYPk',
	privateKey: 'HbiR_WUJmyWrTD2adJJ_vBtmzScUAvXno20SBGV_aHU',
	subject: 'mailto:caddie@example.com',
};

describe('base64url', () => {
	test('round-trips arbitrary bytes', () => {
		const bytes = new Uint8Array([0, 1, 2, 250, 251, 252, 253, 254, 255]);
		expect([...b64urlToBytes(bytesToB64url(bytes))]).toEqual([...bytes]);
	});
});

describe('VAPID JWT', () => {
	test('produces a vapid header whose JWT verifies against the public key, with the endpoint origin as aud', async () => {
		const endpoint = 'https://fcm.googleapis.com/fcm/send/abc123';
		const header = await vapidAuthHeader(endpoint, KEYS, 1_000_000);
		expect(header.startsWith('vapid t=')).toBe(true);
		const t = header.slice('vapid t='.length, header.indexOf(', k='));
		const k = header.slice(header.indexOf('k=') + 2);
		expect(k).toBe(KEYS.publicKey);

		const [h, p, sig] = t.split('.');
		const payload = JSON.parse(new TextDecoder().decode(b64urlToBytes(p!)));
		expect(payload.aud).toBe('https://fcm.googleapis.com');
		expect(payload.sub).toBe(KEYS.subject);
		expect(payload.exp).toBe(1_000_000 + 12 * 60 * 60);

		// Verify the ES256 signature against the public key (the push service does this).
		const pub = b64urlToBytes(KEYS.publicKey);
		const verifyKey = await crypto.subtle.importKey(
			'jwk',
			{ kty: 'EC', crv: 'P-256', x: bytesToB64url(pub.slice(1, 33)), y: bytesToB64url(pub.slice(33, 65)), ext: true },
			{ name: 'ECDSA', namedCurve: 'P-256' },
			false,
			['verify'],
		);
		const ok = await crypto.subtle.verify(
			{ name: 'ECDSA', hash: 'SHA-256' },
			verifyKey,
			new Uint8Array(b64urlToBytes(sig!)),
			new TextEncoder().encode(`${h}.${p}`),
		);
		expect(ok).toBe(true);
	});
});

describe('aes128gcm payload', () => {
	test('encrypts to a valid header: salt(16) + rs(4) + keyid len/65, then ciphertext', async () => {
		// A real-looking subscription: a fresh P-256 public point and a 16-byte auth.
		const ua = (await crypto.subtle.generateKey({ name: 'ECDH', namedCurve: 'P-256' }, true, ['deriveBits'])) as CryptoKeyPair;
		const uaPub = bytesToB64url(new Uint8Array(await crypto.subtle.exportKey('raw', ua.publicKey)));
		const auth = bytesToB64url(crypto.getRandomValues(new Uint8Array(16)));
		const body = await encryptPayload(new TextEncoder().encode('{"title":"hi"}'), uaPub, auth);
		// header is 21 + 65 = 86 bytes, then a non-empty GCM ciphertext (>= 16 tag).
		expect(body.length).toBeGreaterThan(86 + 16);
		const rs = new DataView(body.buffer, body.byteOffset).getUint32(16, false);
		expect(rs).toBe(4096);
		expect(body[20]).toBe(65); // keyid length = raw P-256 point
		expect(body[21]).toBe(0x04); // the as public key is an uncompressed point
	});
});

describe('vapidFromEnv', () => {
	test('returns null without keys, the keys when present', () => {
		expect(vapidFromEnv({})).toBeNull();
		expect(vapidFromEnv({ CADDIE_VAPID_PUBLIC: 'a', CADDIE_VAPID_PRIVATE: 'b' })?.subject).toBe('mailto:caddie@example.com');
		expect(vapidFromEnv({ CADDIE_VAPID_PUBLIC: 'a', CADDIE_VAPID_PRIVATE: 'b', CADDIE_VAPID_SUBJECT: 'mailto:x@y.z' })?.subject).toBe('mailto:x@y.z');
	});
});
